(()=>{function burstAt(el,color='#ffd76b'){if(!el)return;const r=el.getBoundingClientRect();for(let i=0;i<14;i++){const p=document.createElement('i');p.style.cssText=`position:fixed;z-index:40;left:${r.left+r.width/2}px;top:${r.top+r.height/2}px;width:7px;height:7px;border-radius:50%;background:${color};pointer-events:none;transition:transform .65s ease-out,opacity .65s`;document.body.append(p);requestAnimationFrame(()=>{const a=Math.PI*2*i/14,d=35+Math.random()*50;p.style.transform=`translate(${Math.cos(a)*d}px,${Math.sin(a)*d}px) scale(.2)`;p.style.opacity=0});setTimeout(()=>p.remove(),700)}}function shockwave(el){if(!el)return;const ring=document.createElement('span');ring.style.cssText='position:absolute;inset:15%;border:4px solid #fff7a2;border-radius:50%;z-index:9;pointer-events:none;animation:wave .55s ease-out forwards';el.append(ring);burstAt(el);setTimeout(()=>ring.remove(),600)}function evolve(board){board.animate([{filter:'brightness(1)'},{filter:'brightness(2) saturate(1.8)'},{filter:'brightness(1)'}],{duration:850});burstAt(board,'#85fff0')}function victory(){const canvas=document.querySelector('#confetti'),ctx=canvas.getContext('2d');let parts=[];function size(){canvas.width=innerWidth;canvas.height=innerHeight}size();addEventListener('resize',size,{once:true});const colors=['#ffd76b','#ff6851','#52c9f4','#7ee08d','#b87aff'];for(let i=0;i<160;i++)parts.push({x:Math.random()*canvas.width,y:-Math.random()*canvas.height,vx:(Math.random()-.5)*4,vy:2+Math.random()*5,r:3+Math.random()*5,c:colors[i%colors.length],a:Math.random()*6});let frames=0;(function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);parts.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.a+=.12;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);ctx.fillStyle=p.c;ctx.fillRect(-p.r,-p.r/2,p.r*2,p.r);ctx.restore();if(p.y>canvas.height){p.y=-20;p.x=Math.random()*canvas.width}});if(frames++<600)requestAnimationFrame(draw)})()}window.GameFX={shockwave,evolve,victory};const style=document.createElement('style');style.textContent='@keyframes wave{to{inset:-70%;opacity:0;border-width:1px}.cell.win{animation:winPulse .8s infinite alternate}@keyframes winPulse{to{background:#ffd75a88;box-shadow:inset 0 0 24px #fff}}';document.head.append(style)})();